/* ============================================================
   astro-theme-ink · global styles
   Base typography, entrance motion, scrollbar, code blocks.
   ============================================================ */

/* ---- Base ---- */
html {
  scroll-behavior: smooth;
  background-color: hsl(var(--paper) / 1);
}

body {
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

/* Visible keyboard focus (accent ring) for accessibility */
:focus-visible {
  outline: 2px solid hsl(var(--accent) / 0.75);
  outline-offset: 2px;
}

/* Soft aurora at the top of every page — palette-aware via tokens */
#ambient {
  position: absolute;
  inset-inline: 0;
  top: 0;
  height: 24rem;
  pointer-events: none;
  z-index: -1;
  background:
    radial-gradient(55% 55% at 12% 0%, hsl(var(--accent) / 0.12), transparent 65%),
    radial-gradient(45% 45% at 88% 2%, hsl(var(--accent) / 0.1), transparent 65%),
    radial-gradient(38% 38% at 52% 0%, hsl(var(--wash) / 0.7), transparent 72%);
}

/* ---- Entrance motion (staggered by page author) ---- */
@keyframes fade-up {
  from {
    transform: translateY(0.9rem);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

.animate {
  opacity: 0;
  animation: fade-up 420ms cubic-bezier(0.22, 0.61, 0.36, 1) forwards;
}

/* Brief transition when toggling the color theme */
html.theme-switching,
html.theme-switching *,
html.theme-switching *::before,
html.theme-switching *::after {
  transition:
    background-color 0.25s ease,
    color 0.25s ease,
    border-color 0.25s ease,
    fill 0.25s ease !important;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  .animate {
    animation: none;
    opacity: 1;
  }
}

/* ---- Scrollbar: quiet, warm ---- */
:not(html) ::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
:not(html) ::-webkit-scrollbar-thumb {
  background-color: hsl(var(--ink-soft) / 0.28);
  border-radius: 999px;
}
:not(html) ::-webkit-scrollbar-thumb:hover {
  background-color: hsl(var(--accent) / 0.5);
}

/* ============================================================
   Shiki code blocks — ported from astro-theme-pure, the exact look
   of ink.willimt.com. The structure is built at build time by the
   Shiki transformers: `div.astro-code > pre > code` with sticky line
   numbers, optional title, language label, copy button, collapse,
   and diff/highlight notations. Font sizing comes from the prose
   typography preset, exactly like the original theme.
   ============================================================ */

.astro-code {
  margin-block: 1.25rem;
  border-radius: calc(var(--radius) * 1.5);
  background-color: hsl(var(--wash) / var(--un-bg-opacity, 1)) !important;
  display: flex;
  flex-direction: column;

  /* Code container */
  & pre {
    margin: 0;
    padding-top: 0.85rem;
    padding-bottom: 0.85rem;
    padding-inline: 0;
    background: none;
    overflow-x: auto;
    & code {
      display: block;
      width: fit-content;
      min-width: 100%;
      min-height: 1.5rem;
      counter-reset: step;
      counter-increment: step 0;
      /* Number gutter strip */
      &::before {
        position: absolute;
        inset-inline-start: 0;
        width: 2.75rem;
        top: 0.8571429em;
        bottom: 0;
        content: '';
        display: block;
        background-color: hsl(var(--wash) / var(--un-bg-opacity, 1));
        z-index: 1;
      }
      & .line {
        padding-inline-end: 3rem;
        &::before {
          position: sticky;
          content: counter(step);
          counter-increment: step;
          color: hsl(var(--ink-soft) / 0.6);
          background-color: hsl(var(--wash) / var(--un-bg-opacity, 1));
          inset-inline-start: 0;
          justify-content: end;
          display: inline-flex;
          width: 2rem;
          padding-inline-end: 0.75rem;
          box-sizing: content-box;
          z-index: 2;
        }
        &:last-child:empty,
        &:last-child:has(> span:empty:only-child) {
          display: none;
        }
      }
    }
  }
}
html.dark .astro-code pre span {
  color: var(--shiki-dark) !important;
}

/* Title (from ```lang title="..." ) */
.astro-code {
  &:has(code) {
    position: relative;
  }
  &:has(div.title) {
    padding-top: 2rem;
    & code::before {
      top: calc(2rem + 0.8571429em);
    }
  }
  & .title {
    position: absolute;
    top: 0;
    left: 0;
    margin: 0.5rem;
    z-index: 3;
    font-size: 0.875rem;
    color: hsl(var(--ink-soft) / 1);
    padding: 0.25rem 0.75rem;
    border: 1px solid hsl(var(--line) / 1);
    border-radius: 0.5rem;
    background-color: hsl(var(--card) / 1);
  }

  /* Language */
  & .language {
    transition: opacity 0.3s;
    position: absolute;
    top: 0.75rem;
    right: 0;
    font-size: 0.875rem;
    color: hsl(var(--ink-soft) / 1);
    background-color: hsl(var(--wash) / 1);
    padding-inline: 0.25rem 0.75rem;
  }

  /* Copy */
  & button.copy {
    transition: opacity 0.3s;
    opacity: 0;
    position: absolute;
    top: 0.75rem;
    right: 0.75rem;
    user-select: none;
    cursor: pointer;
    color: hsl(var(--ink-soft) / 1);
    background-color: hsl(var(--card) / 1);
    border: 1px solid hsl(var(--line) / 1);
    border-radius: 0.5rem;
    padding: 0.25rem;
    box-sizing: content-box;
    & svg {
      display: block;
      width: 1.25rem;
      height: 1.25rem;
    }
    & .hidden {
      display: none;
    }
    & .success::before {
      content: 'Copied!';
      position: absolute;
      right: 100%;
      top: 0;
      bottom: 0;
      display: flex;
      justify-content: center;
      align-items: center;
      font-size: 0.75rem;
      padding: 0.5rem;
      margin-right: 0.5rem;
      border-radius: 0.25rem;
      color: hsl(var(--ink-soft) / 1);
      background-color: hsl(var(--card) / 1);
      border: 1px solid hsl(var(--line) / 1);
    }
    &.copied {
      & .success {
        display: block;
      }
      & .ready {
        display: none;
      }
    }
  }
  &:hover,
  &:focus-within {
    & button.copy {
      opacity: 1;
    }
    & .language {
      opacity: 0;
    }
  }

  /* Highlighted & diffs */
  & .highlighted,
  & .diff {
    min-width: 100%;
    display: inline-block;
  }
  & .highlighted,
  & .highlighted::before {
    background-color: rgba(149, 166, 183, 0.32) !important;
  }
  & .diff {
    &.remove {
      background-color: rgba(244, 63, 94, 0.16);
      &::before {
        background-color: rgba(244, 63, 94, 0.16);
        content: '-';
      }
    }
    &.add {
      background-color: rgba(16, 185, 129, 0.16);
      &::before {
        background-color: rgba(16, 185, 129, 0.16);
        content: '+';
      }
    }
  }

  /* Collapse */
  & .collapse-toggle {
    z-index: 3;
    padding: 0.25rem;
    user-select: none;
    display: flex;
    justify-content: center;
    align-items: center;
    column-gap: 0.3rem;
    box-sizing: border-box;
    margin: 0;
    cursor: pointer;
    color: hsl(var(--ink-soft) / 1);
    background-color: hsl(var(--card) / 1);
    border-top: 1px solid hsl(var(--line) / 1);
    & svg {
      width: 1.25rem;
      height: 1.25rem;
      transition: transform 0.2s ease;
      transform: rotate(180deg);
    }
    & .desc::before {
      content: 'Collapse';
    }
  }
  &.collapsed {
    & pre {
      max-height: 15rem;
      overflow: hidden;
    }
    & .collapse-toggle {
      margin: 0.5rem;
      border: 1px solid hsl(var(--line) / 1);
      border-radius: 0.5rem;
      & .desc::before {
        content: 'Show all';
      }
      & svg {
        transform: rotate(0deg);
      }
    }
    & .collapse-fade {
      z-index: 2;
      user-select: none;
      pointer-events: none;
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      height: 8rem;
      background: linear-gradient(to bottom, transparent 0%, hsl(var(--wash) / 1) 60%);
    }
  }
}

/* ---- Misc ---- */
hr {
  border-color: hsl(var(--line) / 1);
}

/* Set the prose root directly; the typography preset's extensions target descendants. */
.prose {
  font-size: 1.0625rem;
  line-height: 1.85;
  letter-spacing: 0.012em;
}

.prose.prose-fill {
  width: 100%;
  max-width: 45rem;
  margin-inline: auto;
}

/* Search highlight */
mark {
  background-color: hsl(var(--accent) / 0.18);
  color: inherit;
  border-radius: 0.2em;
  padding-inline: 0.1em;
}

/* ---- Print ---- */
@media print {
  #ambient,
  .site-header,
  .mobile-nav,
  footer,
  #reading-progress,
  .toc,
  .toc-mobile,
  .code-copy,
  .code-lang,
  .collapse-toggle,
  .collapse-fade {
    display: none !important;
  }
  body {
    background: #fff !important;
    color: #000 !important;
  }
  .prose {
    font-size: 12pt;
    line-height: 1.6;
  }
  .prose a {
    text-decoration: underline !important;
    background-image: none !important;
    color: inherit !important;
  }
  .astro-code {
    box-shadow: none;
    border-color: #ccc;
    background-color: #f7f7f7 !important;
  }
  .astro-code code {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
  }
  img {
    max-width: 100% !important;
  }
  pre,
  blockquote {
    break-inside: avoid;
  }
  h2,
  h3 {
    break-after: avoid;
  }
}

/* ---- KaTeX math ---- */
/* Follow the surrounding text color so formulas adapt to dark mode */
.katex {
  color: inherit;
}
/* Long display formulas scroll horizontally instead of overflowing */
.katex-display {
  overflow-x: auto;
  overflow-y: hidden;
  padding: 0.25rem 0;
}

/* ---- Mermaid diagrams ---- */
.prose svg {
  max-width: 100%;
  height: auto;
}

files.src/assets/styles/tokens.css:
/* ============================================================
   astro-theme-ink · design tokens
   Two built-in palettes (switch via the header palette button or
   `site.palette` in site-config.ts):
     - ink    : warm paper (default)
     - fresh  : cool mint, light & airy
   Each palette has a light and a dark variant. All colors are HSL
   triplets consumed through the CSS variables below.
   ============================================================ */

/* ---- Palette: ink (warm paper) · light ---- */
:root {
  color-scheme: light;

  --paper: 42 35% 97%;
  --card: 45 40% 99%;
  --ink: 30 14% 13%;
  --ink-soft: 32 9% 36%;
  --wash: 40 22% 92%;
  --accent: 22 46% 44%;
  --ring: 22 46% 44%;
  --line: 38 20% 86%;
}

/* ---- Palette: ink · dark ---- */
.dark {
  color-scheme: dark;

  --paper: 32 18% 8%;
  --card: 32 14% 11%;
  --ink: 42 32% 92%;
  --ink-soft: 38 10% 66%;
  --wash: 32 12% 14%;
  --accent: 28 72% 68%;
  --ring: 28 72% 68%;
  --line: 32 10% 20%;
}

/* ---- Palette: fresh (haze blue, muted & airy) · light ---- */
.fresh {
  color-scheme: light;

  --paper: 212 28% 97%;
  --card: 212 32% 99%;
  --ink: 215 22% 18%;
  --ink-soft: 214 12% 42%;
  --wash: 212 22% 92%;
  --accent: 213 30% 45%;
  --ring: 213 30% 45%;
  --line: 212 20% 88%;
}

/* ---- Palette: fresh · dark ---- */
.fresh.dark {
  color-scheme: dark;

  --paper: 215 25% 9%;
  --card: 215 22% 12%;
  --ink: 212 30% 92%;
  --ink-soft: 213 12% 68%;
  --wash: 214 20% 15%;
  --accent: 212 45% 72%;
  --ring: 212 45% 72%;
  --line: 213 18% 22%;
}

/* ---- Shape & type (shared) ---- */
:root {
  --radius: 0.5rem;

  --font-serif:
    'Iowan Old Style', 'Palatino Linotype', Georgia, 'Times New Roman', 'Noto Serif SC',
    'Songti SC', 'SimSun', serif;
  --font-sans:
    ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Hiragino Sans GB',
    'Microsoft YaHei', 'Helvetica Neue', Arial, sans-serif;
  --font-mono:
    ui-monospace, 'Cascadia Code', 'JetBrains Mono', 'SF Mono', Consolas, 'Liberation Mono',
    monospace;
}

:root {
  --un-default-border-color: hsl(var(--line) / 1);
}

/* Selection: ink on accent */
::selection {
  background-color: hsl(var(--accent) / 0.22);
}

files.src/assets/styles/waline.css:
/* Waline comment styles.
   Single file: Waline's own stylesheet is imported FIRST, our overrides
   come after — same-specificity rules always resolve in our favour no
   matter how the bundle gets loaded. */

@import '@waline/client/style';

/* ---- Theme tokens for the comment box ---- */
#waline {
  --waline-font-size: 16px;
  --waline-white: hsl(var(--paper) / 1);
  --waline-light-grey: hsl(var(--ink-soft) / 0.6);
  --waline-dark-grey: hsl(var(--ink-soft) / 1);
  --waline-theme-color: hsl(var(--accent) / 1);
  --waline-active-color: hsl(var(--accent) / 1);
  --waline-color: hsl(var(--ink-soft) / 1);
  --waline-bg-color: hsl(var(--card) / 1);
  --waline-bg-color-light: hsl(var(--wash) / 1);
  --waline-bg-color-hover: hsl(var(--wash) / 1);
  --waline-border-color: hsl(var(--line) / 1);
  --waline-disable-bg-color: hsl(var(--wash) / 1);
  --waline-disable-color: hsl(var(--ink-soft) / 0.5);
  --waline-info-bg-color: hsl(var(--wash) / 1);
  --waline-info-color: hsl(var(--ink-soft) / 0.8);
  --waline-info-font-size: 0.75em;
  --waline-border: 1px solid var(--waline-border-color);
  --waline-box-shadow: none;
}

/* ---- Reaction row: single heart + "N Like(s)" (ported from astro-pure) ---- */
#waline .wl-reaction-title,
#waline .wl-reaction-text {
  display: none;
}
#waline .wl-reaction {
  overflow: visible;
  margin-bottom: 0.5em;
}
#waline .wl-reaction-img {
  width: auto;
  display: flex;
  height: 35px;
  align-items: center;
  column-gap: 0.4rem;
}
#waline .wl-reaction-votes {
  position: inherit;
  top: inherit;
  min-width: inherit;
  inset-inline-end: inherit;
  display: flex;
  font-weight: normal;
  border: none;
  background: none;
  color: hsl(var(--ink-soft) / 1);
  padding: 0.2rem 0.4rem;
  border-radius: 6px;
}
#waline .wl-reaction-loading {
  position: inherit;
  top: inherit;
  min-width: inherit;
}
#waline .wl-reaction-item.active .wl-reaction-votes {
  background: var(--waline-theme-color);
  color: var(--waline-bg-color);
}
#waline .wl-reaction-votes:after {
  margin-left: 0.25em;
  content: 'Like(s)';
  display: inline-block;
  clear: both;
  border: 0;
}
#waline .wl-reaction img {
  filter: invert(25%);
}
html.dark #waline .wl-reaction img {
  filter: invert(75%);
}

files.src/components/Comment.astro:
---
import { config } from '@/site-config'

// Waline stylesheet + our overrides live together in waline.css (import
// order guarantees our rules win) — see src/assets/styles/waline.css
import walineStylesheet from '@/assets/styles/waline.css?url'

const server = config.comment.server
const enabled = config.comment.provider === 'waline' && server !== ''
---

{
  enabled && (
    <section class="not-prose mt-14" aria-label="Comments">
      <link rel="stylesheet" href={walineStylesheet} />
      <h2 class="mb-4 flex items-center gap-2 font-serif text-lg font-semibold">
        <span class="i-lucide-message-square size-4 text-accent" aria-hidden="true" />
        Comments
      </h2>
      <div id="waline" />
    </section>
  )
}

<script>
  import { config } from '@/site-config'
  import { withBase } from '@/utils'

  const server = config.comment.server
  const target = document.getElementById('waline')

  // Lazy-load Waline: initialize only when the comment section approaches the
  // viewport — saves ~190 KB of JS on the first paint of every post page.
  const initComment = async () => {
    const { init } = await import('@waline/client')
    init({
      el: '#waline',
      serverURL: server,
      lang: 'zh-CN',
      // page views are handled by the separate <Pageview /> component
      pageview: false,
      imageUploader: false,
      // Single heart "like" reaction — styling lives in waline.css
      reaction: [withBase('/icons/heart-item.svg')],
      locale: {
        reaction0: 'Like(s)',
        reactionTitle: '这篇文章对你有帮助吗？',
        placeholder: 'Welcome to comment. (Email to receive replies. Login is unnecessary)'
      }
    })
  }

  if (server && target) {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          observer.disconnect()
          initComment()
        }
      },
      { rootMargin: '600px 0px' }
    )
    observer.observe(target)
  }
</script>

files.src/components/Header.astro:
---
import { config } from '@/site-config'
import { withBase } from '@/utils'

const pathname = Astro.url.pathname

function isActive(link: string): boolean {
  const href = withBase(link)
  if (href === withBase('/')) return pathname === href
  return pathname === href || pathname.startsWith(`${href}/`)
}
---

<header class="site-header not-prose sticky top-0 z-40 w-full shrink-0" id="site-header">
  <div class="mx-auto flex h-14 max-w-5xl items-center justify-between gap-4 px-5 sm:px-8">
    <!-- Brand -->
    <a href={withBase('/')} class="group flex items-center gap-2" aria-label={config.site.title}>
      <span
        class="i-lucide-feather text-lg text-accent transition-transform duration-300 group-hover:-rotate-12"
        aria-hidden="true"></span>
      <span class="font-serif text-lg font-semibold tracking-wide">{config.site.title}</span>
    </a>

    <!-- Nav -->
    <nav class="hidden items-center gap-1 md:flex" aria-label="Primary navigation">
      {
        config.header.menu.map((item) => (
          <a
            href={withBase(item.link)}
            aria-current={isActive(item.link) ? 'page' : undefined}
            class={[
              'rounded-md px-3 py-1.5 text-sm transition-colors duration-200',
              isActive(item.link) ? 'text-accent' : 'text-ink-soft hover:text-accent'
            ].join(' ')}
          >
            {item.title}
          </a>
        ))
      }
    </nav>

    <!-- Actions -->
    <div class="flex items-center gap-1">
      {
        config.search.enabled && (
          <a
            href={withBase('/search')}
            title="Search"
            aria-label="Search"
            class="icon-btn"
            data-astro-prefetch
          >
            <span class="i-lucide-search size-5" aria-hidden="true" />
          </a>
        )
      }

      <button
        id="palette-toggle"
        type="button"
        class="icon-btn"
        aria-label="Switch palette (ink / fresh)"
        title="Switch palette"
      >
        <span class="i-lucide-feather icon-ink size-5" aria-hidden="true"></span>
        <span class="i-lucide-leaf icon-fresh hidden size-5" aria-hidden="true"></span>
      </button>

      <button
        id="theme-toggle"
        type="button"
        class="icon-btn"
        aria-label="Toggle theme"
        title="Toggle theme"
      >
        <span class="i-lucide-monitor icon-system size-5" aria-hidden="true"></span>
        <span class="i-lucide-sun icon-light size-5" aria-hidden="true"></span>
        <span class="i-lucide-moon icon-dark size-5" aria-hidden="true"></span>
      </button>
    </div>
  </div>
</header>

<!-- Mobile nav: in normal flow (scrolls away), only the slim bar stays sticky -->
<nav
  class="mobile-nav not-prose mx-auto flex max-w-5xl gap-1 overflow-x-auto px-5 pb-2 sm:px-8 md:hidden"
  aria-label="Primary navigation"
>
  {
    config.header.menu.map((item) => (
      <a
        href={withBase(item.link)}
        aria-current={isActive(item.link) ? 'page' : undefined}
        class={[
          'flex-none rounded-md px-3 py-1 text-sm transition-colors duration-200',
          isActive(item.link) ? 'text-accent' : 'text-ink-soft hover:text-accent'
        ].join(' ')}
      >
        {item.title}
      </a>
    ))
  }
</nav>

<style>
  /* Sticky bar: transparent at top, frosted paper once scrolled */
  .site-header {
    transition:
      background-color 0.25s ease,
      border-color 0.25s ease,
      backdrop-filter 0.25s ease;
    border-bottom: 1px solid transparent;
  }
  .site-header.scrolled {
    background-color: color-mix(in srgb, hsl(var(--paper) / 1) 82%, transparent);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-bottom-color: hsl(var(--line) / 1);
  }
  :global(.dark) .site-header.scrolled {
    background-color: color-mix(in srgb, hsl(var(--paper) / 1) 72%, transparent);
  }

  .icon-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.25rem;
    height: 2.25rem;
    border-radius: 0.5rem;
    color: hsl(var(--ink-soft) / 1);
    transition:
      color 0.2s ease,
      background-color 0.2s ease;
  }
  .icon-btn:hover {
    color: hsl(var(--accent) / 1);
    background-color: hsl(var(--wash) / 1);
  }

  /* Mobile nav row: scrollable, no visible scrollbar */
  .mobile-nav {
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
  }
  .mobile-nav::-webkit-scrollbar {
    display: none;
  }

  /* Theme icons: only the icon matching [data-theme] is shown */
  #theme-toggle .icon-system,
  #theme-toggle .icon-light,
  #theme-toggle .icon-dark {
    display: none;
  }

  :global(html[data-theme='light']) #theme-toggle .icon-light,
  :global(html[data-theme='dark']) #theme-toggle .icon-dark,
  :global(html[data-theme='system']) #theme-toggle .icon-system {
    display: inline-block;
  }

  /* Palette icons: feather (ink) by default, leaf (fresh) when active */
  :global(html[data-palette='fresh']) #palette-toggle .icon-ink {
    display: none;
  }
  :global(html[data-palette='fresh']) #palette-toggle .icon-fresh {
    display: inline-block;
  }
</style>

<script>
  const header = document.getElementById('site-header')
  const onScroll = () => header?.classList.toggle('scrolled', window.scrollY > 8)
  onScroll()
  window.addEventListener('scroll', onScroll, { passive: true })
</script>

