---
import type { MarkdownHeading } from 'astro'

interface Props {
  headings: MarkdownHeading[]
}

const { headings } = Astro.props
const toc = headings.filter((h) => h.depth >= 2 && h.depth <= 4)
---

{
  toc.length > 0 && (
    <>
      {/* Mobile: collapsible panel above the article */}
      <details class="toc-mobile not-prose mb-8 rounded-xl border border-line bg-card/60 xl:hidden">
        <summary class="flex cursor-pointer select-none items-center gap-2 px-4 py-3 font-serif text-sm font-semibold text-ink-soft transition-colors hover:text-accent">
          <span class="i-lucide-list-tree size-4" aria-hidden="true" />
          Table of contents
          <span
            class="i-lucide-chevron-down ms-auto size-4 transition-transform duration-300"
            aria-hidden="true"
          />
        </summary>
        <nav class="px-2 pb-3" aria-label="Table of contents (mobile)">
          <ul class="flex flex-col gap-0.5 border-t border-line pt-2">
            {toc.map((h) => (
              <li style={`padding-inline-start: ${(h.depth - 2) * 0.8}rem`}>
                <a
                  href={`#${h.slug}`}
                  class="toc-link block rounded-md px-3 py-1.5 text-sm leading-snug text-ink-soft transition-colors hover:text-accent"
                >
                  {h.text}
                </a>
              </li>
            ))}
          </ul>
        </nav>
      </details>

      {/* Desktop: sticky aside, placed in the right column of the article grid */}
      <aside class="toc not-prose sticky top-24 hidden max-h-[calc(100dvh-8rem)] self-start overflow-y-auto pb-6 xl:col-start-2 xl:block">
        <h2 class="font-serif text-sm font-semibold tracking-widest text-ink-soft">Contents</h2>
        <ul class="mt-3 flex flex-col gap-0.5 border-s border-line ps-4">
          {toc.map((h) => (
            <li style={`padding-inline-start: ${(h.depth - 2) * 0.85}rem`}>
              <a
                href={`#${h.slug}`}
                class="toc-link block rounded-md py-1 text-[13px] leading-snug text-ink-soft transition-colors duration-200 hover:text-accent"
              >
                {h.text}
              </a>
            </li>
          ))}
        </ul>
      </aside>
    </>
  )
}

<style>
  .toc a.active {
    color: hsl(var(--accent) / 1);
    font-weight: 600;
  }
  .toc-mobile[open] summary .i-lucide-chevron-down {
    transform: rotate(180deg);
  }
</style>

<script>
  const links = Array.from(document.querySelectorAll('.toc-link'))
  if (links.length && 'IntersectionObserver' in window) {
    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top)
        if (!visible.length) return
        const id = visible[0].target.id
        links.forEach((link) =>
          link.classList.toggle('active', link.getAttribute('href') === `#${id}`)
        )
      },
      { rootMargin: '-15% 0px -70% 0px' }
    )
    links.forEach((link) => {
      const el = document.getElementById(link.getAttribute('href')!.slice(1))
      if (el) observer.observe(el)
    })
  }
</script>

