  /**
   * Class added to the <pre> element when the current code has diff
   */
  classActivePre?: string
  /**
   * Class added to the <code> element when the current code has diff
   */
  classActiveCode?: string
}

function escapeRegExp(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

export function transformerNotationMap(
  options: TransformerNotationMapOptions = {},
  name = '@shikijs/transformers:notation-map'
): ShikiTransformer {
  const { classMap = {}, classActivePre = undefined, classActiveCode = undefined } = options

  return createCommentNotationTransformer(
    name,
    new RegExp(
      `#?\\s*\\[!code (${Object.keys(classMap).map(escapeRegExp).join('|')})(:\\d+)?\\]`,
      'gi'
    ),
    function ([_, match, range = ':1'], _line, _comment, lines, index) {
      const lineNum = Number.parseInt(range.slice(1), 10)

      for (let i = index; i < Math.min(index + lineNum, lines.length); i++) {
        this.addClassToHast(lines[i], classMap[match])
      }

      if (classActivePre) this.addClassToHast(this.pre, classActivePre)
      if (classActiveCode) this.addClassToHast(this.code, classActiveCode)
      return true
    },
    options.matchAlgorithm
  )
}

// https://github.com/shikijs/shiki/blob/main/packages/transformers/src/shared/notation-transformer.ts
import type { ShikiTransformer, ShikiTransformerContext } from '@shikijs/core'
import type { Element, Text } from 'hast'

import type { ParsedComments } from './shared-parse-comments'
import { parseComments, v1ClearEndCommentPrefix } from './shared-parse-comments'

export type MatchAlgorithm = 'v1' | 'v3'

export interface MatchAlgorithmOptions {
  /**
   * Match algorithm to use
   *
   * @see https://shiki.style/packages/transformers#matching-algorithm
   * @default 'v3'
   */
  matchAlgorithm?: MatchAlgorithm
}

export function createCommentNotationTransformer(
  name: string,
  regex: RegExp,
  onMatch: (
    this: ShikiTransformerContext,
    match: string[],
    line: Element,
    commentNode: Element,
    lines: Element[],
    index: number
  ) => boolean,
  matchAlgorithm: MatchAlgorithm | undefined
): ShikiTransformer {
  if (matchAlgorithm == null) {
    matchAlgorithm = 'v3'
  }

  return {
    name,
    code(code) {
      const lines = code.children.filter((i) => i.type === 'element')
      const linesToRemove: (Element | Text)[] = []

      // biome-ignore lint: the original file used any
      code.data ??= {} as any
      const data = code.data as {
        _shiki_notation?: ParsedComments
      }

      data._shiki_notation ??= parseComments(
        lines,
        ['jsx', 'tsx'].includes(this.options.lang),
        matchAlgorithm
      )
      const parsed = data._shiki_notation

      for (const comment of parsed) {
        if (comment.info[1].length === 0) continue

        let lineIdx = lines.indexOf(comment.line)
        if (comment.isLineCommentOnly && matchAlgorithm !== 'v1') lineIdx++

        let replaced = false
        comment.info[1] = comment.info[1].replace(regex, (...match) => {
          if (onMatch.call(this, match, comment.line, comment.token, lines, lineIdx)) {
            replaced = true
            return ''
          }

          return match[0]
        })

        if (!replaced) continue

        if (matchAlgorithm === 'v1') comment.info[1] = v1ClearEndCommentPrefix(comment.info[1])

        const isEmpty = comment.info[1].trim().length === 0
        // ignore comment node
        if (isEmpty) comment.info[1] = ''

        if (isEmpty && comment.isLineCommentOnly) {
          linesToRemove.push(comment.line)
        } else if (isEmpty && comment.isJsxStyle) {
          comment.line.children.splice(comment.line.children.indexOf(comment.token) - 1, 3)
        } else if (isEmpty) {
          // Handle multi-token comments
          if (comment.additionalTokens) {
            // Remove additional tokens first (in reverse order to maintain indices)
            for (let j = comment.additionalTokens.length - 1; j >= 0; j--) {
              const additionalToken = comment.additionalTokens[j]
              const tokenIndex = comment.line.children.indexOf(additionalToken)
              if (tokenIndex !== -1) {
                comment.line.children.splice(tokenIndex, 1)
              }
            }
          }
          // Remove the main token
          comment.line.children.splice(comment.line.children.indexOf(comment.token), 1)
        } else {
          const head = comment.token.children[0]

          if (head.type === 'text') {
            head.value = comment.info.join('')

            // For multi-token comments, clear the additional tokens
            if (comment.additionalTokens) {
              for (const additionalToken of comment.additionalTokens) {
                const additionalHead = additionalToken.children[0]
                if (additionalHead?.type === 'text') {
                  additionalHead.value = ''
                }
              }
            }
          }
        }
      }

      for (const line of linesToRemove) {
        const index = code.children.indexOf(line)
        const nextLine = code.children[index + 1]
        let removeLength = 1
        if (nextLine?.type === 'text' && nextLine?.value === '\n') removeLength = 2
        code.children.splice(index, removeLength)
      }
    }
  }
}

