// https://github.com/shikijs/shiki/blob/main/packages/transformers/src/shared/parse-comments.ts
import type { Element, ElementContent } from 'hast'

import type { MatchAlgorithm } from './shared-notation-transformer'

export type ParsedComments = {
  line: Element
  token: Element
  info: [prefix: string, content: string, suffix?: string]
  isLineCommentOnly: boolean
  isJsxStyle: boolean
  // For multi-token comments, store the additional tokens that need to be processed
  additionalTokens?: Element[]
}[]

/**
 * some comment formats have to be located at the end of line
 * hence we can skip matching them for other tokens
 */
const matchers: [re: RegExp, endOfLine: boolean][] = [
  [/^(<!--)(.+)(-->)$/, false],
  [/^(\/\*)(.+)(\*\/)$/, false],
  [/^(\/\/|["'#]|;{1,2}|%{1,2}|--)(.*)$/, true],
  /**
   * for multi-line comments like this
   */
  [/^(\*)(.+)$/, true]
]

/**
 * @param lines line tokens
 * @param jsx enable JSX parsing
 * @param matchAlgorithm matching algorithm
 */
export function parseComments(
  lines: Element[],
  jsx: boolean,
  matchAlgorithm: MatchAlgorithm
): ParsedComments {
  const out: ParsedComments = []

  for (const line of lines) {
    // We split nested comments
    if (matchAlgorithm === 'v3') {
      const splittedElements = line.children.flatMap((element, idx) => {
        if (element.type !== 'element') return element

        const token = element.children[0]
        if (token.type !== 'text') return element

        const isLast = idx === line.children.length - 1
        const isComment = matchToken(token.value, isLast)
        if (!isComment) return element
        const rawSplits = token.value.split(/(\s+\/\/)/)
        if (rawSplits.length <= 1) return element

        let splits: string[] = [rawSplits[0]]
        for (let i = 1; i < rawSplits.length; i += 2) {
          splits.push(rawSplits[i] + (rawSplits[i + 1] || ''))
        }
        splits = splits.filter(Boolean)
        if (splits.length <= 1) return element

        return splits.map((split) => {
          return <Element>{
            ...element,
            children: [
              {
                type: 'text',
                value: split
              }
            ]
          }
        })
      })

      if (splittedElements.length !== line.children.length) line.children = splittedElements
    }

    const elements = line.children
    let start = elements.length - 1
    if (matchAlgorithm === 'v1') start = 0
    else if (jsx)
      // one step further for JSX as comment is inside curly brackets
      start = elements.length - 2

    for (let i = Math.max(start, 0); i < elements.length; i++) {
      const token = elements[i]
      if (token.type !== 'element') continue
      const head = token.children.at(0)
      if (head?.type !== 'text') continue

      const isLast = i === elements.length - 1
      let match = matchToken(head.value, isLast)
      let additionalTokens: Element[] | undefined

      // Handle multi-token comments (e.g., rose-pine theme splits "//" and " [!code --]")
      // Check if current token might be the second part of a split comment
      if (!match && i > 0 && head.value.trim().startsWith('[!code')) {
        // Look back to see if the previous token contains the comment prefix
        const prevToken = elements[i - 1]
        if (prevToken?.type === 'element') {
          const prevHead = prevToken.children.at(0)
          if (prevHead?.type === 'text' && prevHead.value.includes('//')) {
            const combinedValue = prevHead.value + head.value
            const combinedMatch = matchToken(combinedValue, isLast)
            if (combinedMatch) {
              match = combinedMatch
              // We need to use the previous token as the main token and this as additional
              // But we need to adjust our approach since we're processing the second token
              // Let's create a special case for this
              out.push({
                info: combinedMatch,
                line,
                token: prevToken, // Use the previous token as the main token
                isLineCommentOnly:
                  elements.length === 2 &&
                  prevToken.children.length === 1 &&
                  token.children.length === 1,
                isJsxStyle: false,
                additionalTokens: [token] // Current token is the additional one
              })
              continue // Skip normal processing for this token
            }
          }
        }
      }

      if (!match) continue

      if (jsx && !isLast && i !== 0) {
        const isJsxStyle = isValue(elements[i - 1], '{') && isValue(elements[i + 1], '}')
        out.push({
          info: match,
          line,
          token,
          isLineCommentOnly: elements.length === 3 && token.children.length === 1,
          isJsxStyle,
          additionalTokens
        })
      } else {
        out.push({
          info: match,
          line,
          token,
          isLineCommentOnly: elements.length === 1 && token.children.length === 1,
          isJsxStyle: false,
          additionalTokens
        })
      }
    }
  }

  return out
}

function isValue(element: ElementContent, value: string): boolean {
  if (element.type !== 'element') return false
  const text = element.children[0]
  if (text.type !== 'text') return false

  return text.value.trim() === value
}

/**
 * @param text text value of comment node
 * @param isLast whether the token is located at the end of line
 */
function matchToken(
  text: string,
  isLast: boolean
): [prefix: string, content: string, suffix?: string] | undefined {
  // no leading and trailing spaces allowed for matchers
  // we extract the spaces
  let trimmed = text.trimStart()
  const spaceFront = text.length - trimmed.length

  trimmed = trimmed.trimEnd()
  const spaceEnd = text.length - trimmed.length - spaceFront

  for (const [matcher, endOfLine] of matchers) {
    if (endOfLine && !isLast) continue

    const result = matcher.exec(trimmed)
    if (!result) continue

    return [
      ' '.repeat(spaceFront) + result[1],
      result[2],
      result[3] ? result[3] + ' '.repeat(spaceEnd) : undefined
    ]
  }
}

/**
 * Remove empty comment prefixes at line end, e.g. `// `
 *
 * For matchAlgorithm v1
 */
export function v1ClearEndCommentPrefix(text: string): string {
  const match = text.match(/(?:\/\/|["'#]|;{1,2}|%{1,2}|--)(\s*)$/)

  if (match && match[1].trim().length === 0) {
    return text.slice(0, match.index)
  }

  return text
}

/**
 * Remove empty comment prefixes at line end, e.g. `// `
 *
 * For matchAlgorithm v3
 */
export function v3ClearEndCommentPrefix(text: string): string {
  const match = text.match(/(?:\/\/|#|;{1,2}|%{1,2}|--)(\s*)$/)

  if (match && match[1].trim().length === 0) {
    return text.slice(0, match.index).trimEnd()
  }

  return text
}

// https://github.com/shikijs/shiki/tree/main/packages/transformers
import type { ShikiTransformer } from '@shikijs/types'
import type { ElementContent } from 'hast'

import { transformerNotationMap } from './shared-notation-map'
import type { MatchAlgorithmOptions } from './shared-notation-transformer'

// https://shiki.style/packages/transformers#transformernotationdiff
// https://github.com/shikijs/shiki/blob/main/packages/transformers/src/transformers/notation-diff.ts
export interface TransformerNotationDiffOptions extends MatchAlgorithmOptions {
  /**
   * Class for added lines
   */
  classLineAdd?: string
  /**
   * Class for removed lines
   */
  classLineRemove?: string
  /**
   * Class added to the <pre> element when the current code has diff
   */
  classActivePre?: string
  /**
   * Class added to the <code> element when the current code has diff
   */
  classActiveCode?: string
}
/**
 * Use `[!code ++]` and `[!code --]` to mark added and removed lines.
 */
export function transformerNotationDiff(
  options: TransformerNotationDiffOptions = {}
): ShikiTransformer {
  const {
    classLineAdd = 'diff add',
    classLineRemove = 'diff remove',
    classActivePre = 'has-diff',
    classActiveCode
  } = options

  return transformerNotationMap(
    {
      classMap: {
        '++': classLineAdd,
        '--': classLineRemove
      },
      classActivePre,
      classActiveCode,
      matchAlgorithm: options.matchAlgorithm
    },
    '@shikijs/transformers:notation-diff'
  )
}

// https://shiki.style/packages/transformers#transformernotationhighlight
// https://github.com/shikijs/shiki/blob/main/packages/transformers/src/transformers/notation-highlight.ts
export interface TransformerNotationHighlightOptions extends MatchAlgorithmOptions {
  /**
   * Class for highlighted lines
   */
  classActiveLine?: string
  /**
   * Class added to the root element when the code has highlighted lines
   */
  classActivePre?: string
  /**
   * Class added to the <code> element when the code has highlighted lines
   */
  classActiveCode?: string
}
/**
 * Allow using `[!code highlight]` notation in code to mark highlighted lines.
 */
export function transformerNotationHighlight(
  options: TransformerNotationHighlightOptions = {}
): ShikiTransformer {
  const {
    classActiveLine = 'highlighted',
    classActivePre = 'has-highlighted',
    classActiveCode
  } = options

  return transformerNotationMap(
    {
      classMap: {
        highlight: classActiveLine,
        hl: classActiveLine
      },
      classActivePre,
      classActiveCode,
      matchAlgorithm: options.matchAlgorithm
    },
    '@shikijs/transformers:notation-highlight'
  )
}

// https://shiki.style/packages/transformers#transformerremovenotationescape
// https://github.com/shikijs/shiki/blob/main/packages/transformers/src/transformers/remove-notation-escape.ts
/**
 * Remove notation escapes.
 * Useful when you want to write `// [!code` in markdown.
 * If you process `// [\!code ...]` expression, you can get `// [!code ...]` in the output.
 */
export function transformerRemoveNotationEscape(): ShikiTransformer {
  return {
    name: '@shikijs/transformers:remove-notation-escape',
    code(hast) {
      function replace(node: ElementContent): void {
        if (node.type === 'text') {
          node.value = node.value.replace('[\\!code', '[!code')
        } else if ('children' in node) {
          for (const child of node.children) {
            replace(child)
          }
        }
      }

      replace(hast)
      return hast
    }
  }
}

